    const matched = await requestJson(
      baseUrl,
      `/scenarios/${id}/events?from=${encodeURIComponent(stamp)}&limit=2&cursor=${encodeURIComponent(cursor)}`
    );
    assert.equal(matched.status, 200);
    assert.deepEqual(
      matched.body.events.map(event => event.sequence),
      [3, 4]
    );
